    /** @param  array<string, mixed>  $context  Runtime account context. */
    public function createTool(string $class, array $context = []): Tool { return new $class($this->resolveService($context)); }

    /** @param  array<string, mixed>  $context  Runtime account context. */
    private function resolveService(array $context = []): MicrosoftPlannerService
    {
        $account = $context['account'] ?? null;
        if ($account !== null) {
            $creds = app(CredentialResolver::class);
            return new MicrosoftPlannerService(accessToken: $creds->get('microsoft-planner', 'access_token', '', $account), baseUrl: $creds->get('microsoft-planner', 'base_url', 'https://graph.microsoft.com/v1.0', $account));
        }

        return app(MicrosoftPlannerService::class);
    }

    public function scriptDocsPath(): ?string { return __DIR__ . '/../script-docs/microsoft-planner.md'; }
    public function isIntegration(): bool { return true; }
